'use strict';
async function importImage(file){if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>LIMITS.file){toast('请使用 12MB 以内的 PNG、JPG 或 WebP',true);return}const reader=new FileReader();reader.onload=async()=>{try{const im=await imageOf(reader.result);if(im.width*im.height>LIMITS.pixels)throw new Error('原型最多支持 600 万像素');confirmNewSession(async()=>{await freshState(reader.result,file.name,false);setPage('editor');banner('已导入外部图片。没有自动识别保护区，请用保护笔手工锁定不应修改的内容。','amber');toast('新会话已创建；图片没有上传')})}catch(e){toast(e.message,true)}};reader.readAsDataURL(file)}
function confirmNewSession(action){if(jobBusy){toast('请先完成或取消演示任务',true);return}modal('开始一个新会话？','这会替换本浏览器当前演示会话。旧工程不会被写入新会话。',`<p class="form-note">当前有 ${state.revisions.length} 个版本、${state.attempts.length} 次演示尝试。需要保留时，请先点击“保存当前工程”。这与恢复历史版本不同。</p>`,`<button class="btn" id="backupBeforeReset">保存当前工程</button><button class="btn" data-close>取消</button><button class="btn primary" id="newSessionConfirm">确认开始新会话</button>`);$('backupBeforeReset').onclick=exportProject;$('newSessionConfirm').onclick=async()=>{closeModal();images=new Map();await action()}}
function bindGoto(root=document){root.querySelectorAll('[data-goto]').forEach(el=>el.onclick=()=>setPage(el.dataset.goto))}
function bind(){document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>setPage(el.dataset.page));bindGoto();document.querySelectorAll('[data-tool]').forEach(el=>el.onclick=()=>setTool(el.dataset.tool));document.querySelectorAll('[data-preset]').forEach(el=>el.onclick=()=>preset(el.dataset.preset));$('brushSize').oninput=()=>{updateToolLabel();draw()};$('undoStroke').onclick=undoStroke;$('redoStroke').onclick=redoStroke;$('clearMask').onclick=()=>{if(!jobBusy)commitStroke({kind:'clear',time:now()})};$('prompt').oninput=()=>{updatePromptCount();scheduleSave()};$('demoEffect').onchange=()=>{scheduleSave();if($('demoEffect').value==='label'&&$('lockLabels').checked)toast('修改房名时，请预先明确解除房名保护并重新预览范围',true)};['lockWalls','lockLabels'].forEach(id=>$(id).onchange=()=>{rebuildMasks();scheduleSave()});['showEdit','showProtect','showContext'].forEach(id=>$(id).onchange=draw);$('zoomIn').onclick=()=>zoom(1.2);$('zoomOut').onclick=()=>zoom(1/1.2);$('fitView').onclick=fitCanvas;$('previewScope').onclick=scopePreview;$('cancelJob').onclick=()=>{if(activeJob){activeJob.cancelled=true;$('cancelJob').disabled=true;$('progressText').textContent='正在取消演示任务'}};$('openGuide').onclick=()=>setPage('guide');$('startGuide').onclick=()=>{if(state.isSample){preset('racks');toast('示例已准备好。点击“预览修改范围”继续。')}else{toast('当前不是内置示例，可重置演示会话后体验',true);setPage('editor')}};$('undoVersion').onclick=()=>{if(head().parent)restoreDialog(head().parent,true)};$('eventFilter').onchange=renderAudit;$('exportProject').onclick=exportProject;$('exportAudit').onclick=exportAudit;$('importImageBtn').onclick=()=>{if(jobBusy){toast('请先完成或取消任务',true);return}$('imageInput').click()};$('imageInput').onchange=()=>{importImage($('imageInput').files[0]);$('imageInput').value=''};$('importProjectBtn').onclick=()=>{if(jobBusy){toast('请先取消正在进行的任务',true);return}$('projectInput').click()};$('projectInput').onchange=async()=>{const file=$('projectInput').files[0];$('projectInput').value='';if(!file)return;try{if(file.size>LIMITS.project)throw new Error('工程文件超过 40MB 原型限制');const loaded=await validateProject(JSON.parse(await file.text()));confirmNewSession(async()=>{state=loaded;for(const a of state.attempts)if(a.status==='running'){a.status='cancelled';a.error='重开工程时结束了未完成的演示'}selectedRevision=state.headId;selectedCandidate=state.attempts.filter(a=>a.final).at(-1)?.id||null;currentImage=await imageOf(head().image);applyDraftToUI();rebuildMasks();fitCanvas();addEvent('project.imported','恢复导出的工程文件',{head:state.headId,revisions:state.revisions.length,backend:'NONE'},'version');updateChrome();setPage('history');scheduleSave();toast('工程与版本历史已恢复')})}catch(e){toast('工程导入失败：'+e.message,true)}};$('resetDemo').onclick=()=>confirmNewSession(async()=>{await freshState();setPage('editor');banner();toast('已重新载入演示原图')});const c=$('editorCanvas');c.addEventListener('pointerdown',pointerDown);c.addEventListener('pointermove',pointerMove);c.addEventListener('pointerup',endPointer);c.addEventListener('pointercancel',endPointer);c.addEventListener('lostpointercapture',endPointer);c.addEventListener('pointerleave',()=>{if(!currentStroke){pointerPos=null;draw()}});c.addEventListener('wheel',ev=>{ev.preventDefault();const rect=c.getBoundingClientRect();zoom(ev.deltaY<0?1.1:1/1.1,ev.clientX-rect.left,ev.clientY-rect.top)},{passive:false});window.addEventListener('blur',()=>{endPointer();spaceHeld=false});document.addEventListener('visibilitychange',()=>{if(document.hidden){endPointer();persist()}});window.addEventListener('pagehide',persist);document.addEventListener('keydown',e=>{if($('modalRoot').children.length){if(e.key==='Escape'){closeModal();return}if(e.key==='Tab'){const focusable=[...$('modalRoot').querySelectorAll('button:not(:disabled),input:not(:disabled),textarea,select,[tabindex="0"]')];if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault()}}return}if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(page==='editor'){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redoStroke():undoStroke();return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();redoStroke();return}if(e.code==='Space'){e.preventDefault();spaceHeld=true;c.style.cursor='grab'}const shortcuts={b:'brush',e:'erase',p:'protect',r:'rect',h:'pan'};if(shortcuts[e.key.toLowerCase()]&&!e.ctrlKey&&!e.metaKey)setTool(shortcuts[e.key.toLowerCase()]);if(e.key==='['||e.key===']'){$('brushSize').value=clamp(Number($('brushSize').value)+(e.key===']'?4:-4),4,90);updateToolLabel()}}});document.addEventListener('keyup',e=>{if(e.code==='Space'){spaceHeld=false;c.style.cursor=tool==='pan'?'grab':'crosshair'}});resizeObserver=new ResizeObserver(()=>resizeCanvas());resizeObserver.observe($('stage'))}
async function init(){bind();try{db=await openDB();const saved=await loadStore();if(saved){state=await validateProject(saved);for(const a of state.attempts)if(a.status==='running'){a.status='cancelled';a.error='页面重启，结束未完成演示任务';addEvent('attempt.interrupted','重开页面后标记未完成演示',{candidate:a.id,model_executed:false},'request')}currentImage=await imageOf(head().image);selectedRevision=state.headId;selectedCandidate=state.attempts.filter(a=>a.final).at(-1)?.id||null;applyDraftToUI();fitCanvas();rebuildMasks();updateChrome();banner(`已恢复本浏览器会话：当前 ${state.headId}，共 ${state.revisions.length} 个版本。`);scheduleSave()}else await freshState()}catch(e){$('storageWarning').classList.remove('hidden');db=null;await freshState()}resizeCanvas();updateChrome();document.body.dataset.ready='true'}
// Minimal read-only diagnostics for QA; no bridge to any model or network service.
window.P2Demo={summary:()=>({page,head:state?.headId,revisions:state?.revisions.map(({image,...r})=>r),attempts:state?.attempts.map(({raw,final,diff,mask,protection,strokes,...a})=>a),mask:structuredClone(maskStats),draftCommands:state?.draft.commands.length,draftRedo:state?.draft.redo.length,view:structuredClone(view),size:state?[state.width,state.height]:null,events:state?.events.length,jobBusy}),exportState:()=>structuredClone(state)};
init().catch(e=>{toast('初始化失败：'+e.message,true);console.error(e)});
